<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../includes/functions.php';require_admin();
$dateFrom=$_GET['date_from']??date('Y-m-01');$dateTo=$_GET['date_to']??date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dateFrom))$dateFrom=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dateTo))$dateTo=date('Y-m-d');if($dateFrom>$dateTo){[$dateFrom,$dateTo]=[$dateTo,$dateFrom];}
$dailyStmt=$pdo->prepare("SELECT DATE(order_date) report_date,COUNT(*) order_count,SUM(total_amount) total FROM orders WHERE order_status<>'Cancelled' AND DATE(order_date) BETWEEN ? AND ? GROUP BY DATE(order_date) ORDER BY report_date DESC");$dailyStmt->execute([$dateFrom,$dateTo]);$daily=$dailyStmt->fetchAll();
$summaryStmt=$pdo->prepare("SELECT COUNT(*) order_count,COALESCE(SUM(total_amount),0) total FROM orders WHERE order_status<>'Cancelled' AND DATE(order_date) BETWEEN ? AND ?");$summaryStmt->execute([$dateFrom,$dateTo]);$summary=$summaryStmt->fetch();
$range=[$dateFrom,$dateTo];
$byPay=$pdo->prepare("SELECT p.payment_method,COUNT(*) n,SUM(o.total_amount) total FROM orders o JOIN payments p ON p.order_id=o.order_id WHERE o.order_status<>'Cancelled' AND DATE(o.order_date) BETWEEN ? AND ? GROUP BY p.payment_method ORDER BY total DESC");$byPay->execute($range);$byPay=$byPay->fetchAll();
$byPlace=$pdo->prepare("SELECT COALESCE(NULLIF(delivery_city,''),'Not recorded') city,COALESCE(NULLIF(delivery_zone,''),'Standard fee') zone,COUNT(*) n,SUM(total_amount) total FROM orders WHERE order_status<>'Cancelled' AND DATE(order_date) BETWEEN ? AND ? GROUP BY city,zone ORDER BY total DESC LIMIT 25");$byPlace->execute($range);$byPlace=$byPlace->fetchAll();
$top=$pdo->prepare("SELECT p.product_name,SUM(oi.quantity) units,SUM(oi.subtotal) revenue,SUM(CASE WHEN p.cost_price IS NOT NULL THEN oi.subtotal-oi.quantity*p.cost_price END) profit,SUM(p.cost_price IS NULL) no_cost FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.order_status<>'Cancelled' AND DATE(o.order_date) BETWEEN ? AND ? GROUP BY p.product_id,p.product_name ORDER BY units DESC LIMIT 15");$top->execute($range);$top=$top->fetchAll();
$slow=$pdo->query("SELECT p.product_name,p.stock_quantity,p.unit,COALESCE(SUM(CASE WHEN o.order_status<>'Cancelled' AND o.order_date>=NOW()-INTERVAL 90 DAY THEN oi.quantity END),0) sold90 FROM products p LEFT JOIN order_items oi ON oi.product_id=p.product_id LEFT JOIN orders o ON o.order_id=oi.order_id WHERE p.stock_quantity>0 GROUP BY p.product_id,p.product_name,p.stock_quantity,p.unit ORDER BY sold90 ASC,p.stock_quantity DESC LIMIT 15")->fetchAll();
$pageTitle='Sales Reports';require __DIR__.'/../includes/header.php';require __DIR__.'/nav.php';
?>
<div class="page-head"><div><h1>Sales Reports</h1><p class="muted">Date-filtered sales summary; cancelled orders are excluded.</p></div><div><a class="btn btn-primary" href="<?=BASE_URL?>/admin/export.php?type=sales">Export Excel-compatible CSV</a> <a class="btn btn-outline" href="<?=BASE_URL?>/admin/export.php?type=inventory">Export Inventory CSV</a> <button class="btn btn-outline" onclick="window.print()">Print / Save PDF</button></div></div>
<div class="card u-mb-18"><form method="get" class="form-row"><div><label>From</label><input type="date" name="date_from" value="<?=e($dateFrom)?>" required></div><div><label>To</label><input type="date" name="date_to" value="<?=e($dateTo)?>" required></div><div class="u-self-end"><button class="btn btn-primary">Apply Date Range</button> <a class="btn btn-outline" href="reports.php">Reset</a></div></form><p><b><?= (int)$summary['order_count'] ?> non-cancelled orders</b> · <b><?=money($summary['total'])?> total sales</b></p></div>
<div class="card u-mb-18"><h2>Daily Sales — <?=e($dateFrom)?> to <?=e($dateTo)?></h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Orders</th><th>Total sales</th></tr></thead><tbody><?php foreach($daily as $r): ?><tr><td><?= e($r['report_date']) ?></td><td><?= $r['order_count'] ?></td><td><?= money($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$daily): ?><tr><td colspan="3">No sales recorded.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card u-mb-18"><h2>Payment methods — <?=e($dateFrom)?> to <?=e($dateTo)?></h2><div class="table-wrap"><table><thead><tr><th>Method</th><th>Orders</th><th>Total</th></tr></thead><tbody><?php foreach($byPay as $r): ?><tr><td><?= e($r['payment_method']) ?></td><td><?= (int)$r['n'] ?></td><td><?= money($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$byPay): ?><tr><td colspan="3" class="muted">No sales in this range.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card u-mb-18"><h2>Revenue by city and delivery zone</h2><div class="table-wrap"><table><thead><tr><th>City</th><th>Zone</th><th>Orders</th><th>Total</th></tr></thead><tbody><?php foreach($byPlace as $r): ?><tr><td><?= e($r['city']) ?></td><td><?= e($r['zone']) ?></td><td><?= (int)$r['n'] ?></td><td><?= money($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$byPlace): ?><tr><td colspan="4" class="muted">No sales in this range.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card u-mb-18"><h2>Best sellers and estimated profit</h2><p class="muted small">Top 15 by units sold in the date range. Profit uses each product's <em>current</em> cost price (set it under Product Management), so it is an estimate and does not include delivery fees. A dash means no cost price is set.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th><th>Est. profit</th></tr></thead><tbody><?php foreach($top as $r): ?><tr><td><?= e($r['product_name']) ?></td><td><?= (int)$r['units'] ?></td><td><?= money($r['revenue']) ?></td><td><?= $r['profit']===null||(int)$r['no_cost']>0 ? '—' : money($r['profit']) ?></td></tr><?php endforeach; ?><?php if(!$top): ?><tr><td colspan="4" class="muted">No sales in this range.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card u-mb-18"><h2>Slow-moving stock (last 90 days)</h2><p class="muted small">In-stock products that sold the least, a hint for what to discount or stop reordering.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>In stock</th><th>Sold in 90 days</th></tr></thead><tbody><?php foreach($slow as $r): ?><tr><td><?= e($r['product_name']) ?></td><td><?= (int)$r['stock_quantity'] ?> <?= e($r['unit']) ?></td><td><?= (int)$r['sold90'] ?></td></tr><?php endforeach; ?><?php if(!$slow): ?><tr><td colspan="3" class="muted">No products in stock.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
